css:
/* VELVET CASKET (theme author guide v1.5, contract 1)
   One idea: every container is a coffin. Messages stand as upright coffins with a finial on the
   head, the message box is a coffin laid on its side, Home widgets are a row of coffins, dialogs are
   coffin lids, buttons are coffin tags, avatars are mourning cameos, and an iron cemetery fence runs
   under the top bar.
   Day  = PASTEL GOTH: lilac, mint, baby pink, thick black sticker outlines, bats and bow-skulls.
   Night = TRADITIONAL GOTH: black and oxblood velvet, antique silver trim, iron crosses, candlelight. */

:root{
  --mari-tokens-version:1;
  /* coffin geometry (px so the shape survives any height) */
  --vc-head:22px;   /* how far the head is cut in from each side */
  --vc-sh:22px;     /* how far down the shoulders sit */
  --vc-foot:14px;   /* how far the foot tapers in */
  --vc-bw:2px;      /* outline thickness */
  --vc-coffin:polygon(var(--vc-head) 0,calc(100% - var(--vc-head)) 0,100% var(--vc-sh),calc(100% - var(--vc-foot)) 100%,var(--vc-foot) 100%,0 var(--vc-sh));
  --vc-coffin-in:polygon(calc(var(--vc-head) - 1px) 0,calc(100% - var(--vc-head) + 1px) 0,100% calc(var(--vc-sh) - 1px),calc(100% - var(--vc-foot)) 100%,var(--vc-foot) 100%,0 calc(var(--vc-sh) - 1px));
  /* coffin on its side: head on the left, foot on the right */
  --vc-coffin-side:polygon(0 12px,30px 0,calc(100% - 8px) 6px,100% 50%,calc(100% - 8px) calc(100% - 6px),30px 100%,0 calc(100% - 12px));
  /* coffin tag for buttons and pills */
  --vc-tag:polygon(8px 0,calc(100% - 8px) 0,100% 50%,calc(100% - 8px) 100%,8px 100%,0 50%);

  --vc-blackletter:"UnifrakturCook","Old English Text MT",serif;
  --vc-serif:"EB Garamond",Garamond,"Times New Roman",serif;
  --vc-plate:"Cormorant SC","EB Garamond",serif;

  --radius:2px;
  --mari-font-ui:var(--vc-serif);
  --mari-font-heading:var(--vc-blackletter);
  --mari-font-chat:var(--vc-serif);
  --ov-serif:var(--vc-blackletter);
  --mari-chat-font-size:17px;
  --mari-chat-line-height:1.6;
  --mari-message-measure:72ch;
  --mari-paragraph-gap:0.8em;
  --mari-dialogue-weight:500;
  --mari-text-outline:0;
  --mari-min-ui-text:12px;
  --mari-toast-font-size:1rem;
  --mari-selected-tint:var(--primary);
  --mari-msg-head-rule:var(--vc-head-rule);
  --mari-home-art:none;
  --mari-home-widget-radius:0;
  --mari-home-widget-border-width:0;
  --mari-home-widget-font:var(--vc-serif);
  --mari-home-widget-title-font:var(--vc-blackletter);
  --mari-home-widget-title-size:1.6rem;
  --mari-home-widget-eyebrow-size:0.8125rem;
  --mari-home-widget-text-size:0.9375rem;
  --mari-home-widget-action-size:0.9375rem;
  --mari-home-shortcut-size:1rem;
  --mari-top-bar-plate-radius:0;
  --mari-composer-placeholder:"Whisper into the dark...";
  --mari-chat-wash:none;
  --mari-chat-row-art-opacity:0;
  --marinara-theme-accent-pulse:none;
  --glow-primary:transparent; --glow-accent:transparent;
  --mari-chat-column:46rem;
  --mari-art-saturation-1:28%; --mari-art-saturation-2:24%;
  --mari-pinned-speaker:on;
  --mari-phone-avatar:hidden;
}

/* ── NIGHT · traditional goth ─────────────────────────────── */
:root,:root[data-theme="dark"]{
  --vc-ground:#0b0709; --vc-ink:#efe6e8; --vc-mute:#bfaeb5; --vc-faint:#9a8a91;
  --vc-hair:rgba(185,170,180,.28);
  --vc-trim:#9a8f99;              /* antique silver outline */
  --vc-lining:#170a10;            /* coffin lining under the velvet */
  --vc-lining-user:#1d0d14;
  --vc-velvet:url("theme:velvet-tile.webp");
  --vc-panel:rgba(16,8,12,.92);
  --vc-bar:#0e0709;
  --vc-accent:#a3213a;            /* oxblood */
  --vc-accent-ink:#f1a7b3;        /* readable crimson for text on black */
  --vc-gold:#dcb874;              /* candle gold */
  --vc-finial:url("theme:or-cross.webp");
  --vc-finial-user:url("theme:or-rose.webp");
  --vc-finial-latest:url("theme:or-candle.webp");
  --vc-crest:url("theme:or-crest.webp");
  --vc-scene-break:url("theme:or-fleur.webp");
  --vc-fence:url("theme:fence-night.svg");
  --mari-icon-send:url("theme:send-night.svg");
  --vc-backdrop:url("theme:night-chapel.webp");
  --vc-backdrop-wash:linear-gradient(rgba(11,7,9,0),rgba(11,7,9,0));
  --mari-art-lightness-1:20%; --mari-art-lightness-2:12%;
  --vc-online:#4fc79a;
  --vc-name:var(--vc-gold);
  --vc-latest-trim:#a3213a;
  --vc-head-rule:1px solid rgba(185,170,180,.3);
  --vc-mint:#cfc6d2;
  --vc-mint-ink:#cfc6d2;
  --vc-rail:url("theme:rail-night.svg");
  --vc-lid:url("theme:lid-night.svg");
  --vc-sidebar-bg:linear-gradient(rgba(14,7,10,.28),rgba(14,7,10,.4)),url("theme:velvet-tile.webp") 0 0 / 512px repeat;
  --vc-lining-layers:linear-gradient(rgba(21,9,14,.5),rgba(21,9,14,.58)),var(--vc-velvet) 0 0 / 512px repeat,#170a10;
  --vc-lining-user-layers:linear-gradient(rgba(34,12,22,.46),rgba(34,12,22,.54)),var(--vc-velvet) 0 0 / 512px repeat,#1d0d14;
}

/* ── DAY · pastel goth ─────────────────────────────────────── */
:root[data-theme="light"]{
  --vc-ground:#ece2fb; --vc-ink:#1f1226; --vc-mute:#4f3a5c; --vc-faint:#6a5677;
  --vc-hair:rgba(26,16,32,.22);
  --vc-trim:#1a1020;              /* thick black sticker outline */
  --vc-lining:#f8f2ff;            /* lilac paper */
  --vc-lining-user:#fde6f1;       /* baby pink */
  --vc-velvet:none;
  --vc-panel:rgba(244,236,253,.93);
  --vc-bar:#f3eafd;
  --vc-accent:#c42d7a;            /* hot baby-pink, white text passes */
  --vc-accent-ink:#7a2a6e;
  --vc-gold:#2f7d63;              /* mint ink for names */
  --vc-finial:url("theme:st-bat.webp");
  --vc-finial-user:url("theme:st-skull.webp");
  --vc-finial-latest:url("theme:st-heartbat.webp");
  --vc-crest:url("theme:st-holo.webp");
  --vc-scene-break:url("theme:st-holo.webp");
  --vc-fence:url("theme:fence-day.svg");
  --vc-bw:2.5px;
  --mari-icon-send:url("theme:send-day.svg");
  --vc-backdrop:url("theme:day-chapel.webp");
  --vc-backdrop-wash:linear-gradient(rgba(236,226,251,0),rgba(236,226,251,0));
  --mari-art-lightness-1:84%; --mari-art-lightness-2:78%;
  --vc-online:#17694a;
  --vc-name:#6b1f6e;
  --vc-mint:#9fe8c8;
  --vc-mint-ink:#1d6b4f;
  --vc-latest-trim:#1a1020;
  --vc-head-rule:2px dashed #7fd6b0;
  --vc-rail:url("theme:rail-day.svg");
  --vc-lid:url("theme:lid-day.svg");
  --vc-sidebar-bg:linear-gradient(rgba(246,240,254,.9),rgba(246,240,254,.9)),url("theme:day-pattern.webp") 0 0 / 320px repeat;
  --vc-lining-layers:#ecdfff;
  --vc-lining-user-layers:#ffdcec;
  --vc-lining-latest:linear-gradient(#ecdfff,#ecdfff) padding-box;
}

:root,:root[data-theme="dark"],:root[data-theme="light"]{
  --background:var(--vc-ground); --foreground:var(--vc-ink);
  --card:var(--vc-panel); --card-foreground:var(--vc-ink);
  --popover:var(--vc-panel); --popover-foreground:var(--vc-ink);
  --primary:var(--vc-accent); --primary-foreground:#fff;
  --secondary:color-mix(in srgb,var(--vc-ink) 8%,var(--vc-ground)); --secondary-foreground:var(--vc-ink);
  --muted:color-mix(in srgb,var(--vc-ink) 6%,var(--vc-ground)); --muted-foreground:var(--vc-mute);
  --accent:color-mix(in srgb,var(--vc-accent) 16%,var(--vc-ground)); --accent-foreground:var(--vc-ink);
  --destructive:#b3123a; --destructive-foreground:#fff;
  --border:var(--vc-hair); --input:var(--vc-hair); --ring:var(--vc-accent);
  --sidebar:var(--vc-panel); --sidebar-foreground:var(--vc-ink); --sidebar-border:var(--vc-hair);
  --sidebar-accent:color-mix(in srgb,var(--vc-accent) 14%,transparent); --sidebar-accent-foreground:var(--vc-ink);
  --ov-line:var(--vc-hair); --ov-text:var(--vc-ink); --ov-muted:var(--vc-mute); --ov-dim:var(--vc-faint);
  --ov-accent:var(--vc-accent-ink);
  --ov-hover:color-mix(in srgb,var(--vc-ink) 7%,transparent);
  --ov-active-bg:color-mix(in srgb,var(--vc-accent) 18%,transparent);
  --ov-mode-conversation:var(--vc-accent-ink); --ov-mode-roleplay:var(--vc-accent-ink); --ov-mode-game:var(--vc-gold);
  --mari-mode-conversation:var(--vc-accent-ink); --mari-mode-roleplay:var(--vc-accent-ink); --mari-mode-game:var(--vc-gold);
  --mari-home-pink:var(--vc-accent-ink); --mari-home-violet:var(--vc-gold);
  --mari-chrome-accent:var(--vc-accent-ink);
  --mari-chrome-muted:var(--vc-mute);
  --mari-message-time:var(--vc-faint);
  --mari-message-actions:var(--vc-mute);
  --mari-swipe-counter:var(--vc-mute);
  --mari-dialogue-color:var(--vc-accent-ink);
  --mari-home-widget-bg:transparent;
  --mari-home-widget-title-color:var(--vc-ink);
  --mari-home-widget-muted:var(--vc-mute);
  --mari-home-widget-eyebrow-color:var(--vc-accent-ink);
  --mari-home-wash:transparent;
  --mari-page-veil:color-mix(in srgb,var(--vc-ground) 82%,transparent);
  --mari-chat-header-bg:none;
  --mari-scrim:color-mix(in srgb,var(--vc-ground) 72%,transparent);
  --mari-top-bar-plate:color-mix(in srgb,var(--vc-ground) 88%,transparent);
  --mari-status-online:var(--vc-online); --mari-status-idle:var(--vc-gold); --mari-status-dnd:#c42d4a; --mari-status-offline:var(--vc-faint);
  --mari-gauge-ok:#3fb68b; --mari-gauge-warn:#d39b3a; --mari-gauge-danger:#c42d4a;
  --mari-game-combat:var(--vc-accent); --mari-game-combat-text:#fff;
  --mari-game-combat-bg:var(--vc-accent); --mari-game-combat-bg-hover:color-mix(in srgb,var(--vc-accent) 85%,#000); --mari-game-combat-border:var(--vc-accent);
  --mari-stage-empty-bg:var(--vc-backdrop-wash),var(--vc-backdrop) center bottom / cover no-repeat,var(--vc-ground);
  --mari-user-avatar-placeholder:radial-gradient(circle at 50% 38%,var(--vc-trim) 0 22%,transparent 23%),radial-gradient(ellipse 60% 40% at 50% 100%,var(--vc-trim) 0 70%,transparent 71%),var(--vc-lining);
  --mari-focus-ring-color:var(--vc-accent-ink);
  --mari-top-bar-bg:var(--vc-fence) 0 100% / auto 44px repeat-x,linear-gradient(var(--vc-bar),var(--vc-bar));
}
/* ── Backdrop: the same chapel and graveyard, pastel by day, candlelit by night ── */
:root{
  --mari-app-backdrop-layers:var(--vc-backdrop-wash),var(--vc-backdrop) center bottom / cover no-repeat,var(--vc-ground);
  --mari-user-avatar-image:var(--vc-cameo);
  --mari-card-art-placeholder:var(--vc-cameo) center / auto 70% no-repeat,var(--vc-card-ph);
}
:root,:root[data-theme="dark"]{ --vc-cameo:url("theme:cameo-night.webp"); --vc-card-ph:radial-gradient(ellipse at 50% 40%,#3a0d19,#120609 75%); }
:root[data-theme="light"]{ --vc-cameo:url("theme:cameo-day.webp"); --vc-card-ph:radial-gradient(ellipse at 50% 40%,#fbe7f2,#dccbf6 75%); }
@media (orientation:portrait){
  :root[data-overhaul="mobile"]{ --vc-backdrop:url("theme:night-phone.webp"); }
  :root[data-overhaul="mobile"][data-theme="light"]{ --vc-backdrop:url("theme:day-phone.webp"); }
}
/* weather greys the graveyard over: rain and storm darken, snow pales, fog thickens */
:root[data-mari-weather="rain"],:root[data-mari-weather="storm"]{ --vc-backdrop:url("theme:night-chapel-storm.webp"); --vc-backdrop-wash:linear-gradient(rgba(14,10,22,.15),rgba(20,10,24,.1)); }
:root[data-theme="light"][data-mari-weather="rain"],:root[data-theme="light"][data-mari-weather="storm"]{ --vc-backdrop-wash:linear-gradient(rgba(150,130,190,.38),rgba(190,170,215,.25)); }
:root[data-mari-weather="snow"],:root[data-mari-weather="hail"]{ --vc-backdrop-wash:linear-gradient(rgba(200,190,210,.12),rgba(235,230,240,.22)); }
:root[data-theme="light"][data-mari-weather="snow"],:root[data-theme="light"][data-mari-weather="hail"]{ --vc-backdrop-wash:linear-gradient(rgba(255,255,255,.3),rgba(255,255,255,.45)); }
:root[data-mari-weather="fog"]{ --vc-backdrop-wash:linear-gradient(rgba(60,36,46,.3),rgba(90,52,64,.45)); }
:root[data-theme="light"][data-mari-weather="fog"]{ --vc-backdrop-wash:linear-gradient(rgba(236,226,251,.45),rgba(236,226,251,.6)); }

/* ── Top bar: a cemetery fence runs along its foot ─────────── */
[data-component="TopBar"]{
  font-family:var(--vc-plate); letter-spacing:.02em; border-bottom:0 !important;
  height:auto !important; min-height:86px; padding-bottom:44px !important; align-items:flex-start;
}
[data-component="TopBar"] .ov-tab,[data-component="TopBar"] .ov-text-btn{ clip-path:var(--vc-tag); padding-inline:14px; border-radius:0; }
[data-component="TopBar"] .ov-tab.is-on{ background:color-mix(in srgb,var(--vc-accent) 30%,var(--vc-ground)); color:var(--vc-ink); }
:root[data-theme="light"] [data-component="TopBar"] .ov-tab.is-on{ background:color-mix(in srgb,var(--vc-accent) 16%,#fff); }
[data-component="TopBar"] .ov-tab__label{ font-weight:700; }

/* ── Sidebars: an iron railing on the inner edge ──────────── */
[data-component="ChatSidebar"]{ font-family:var(--vc-serif); background:var(--vc-rail) right top / 14px 64px repeat-y,var(--vc-sidebar-bg) !important; padding-right:12px; }
[data-component="RightPanelDesktop"]{ background:var(--vc-rail) left top / 14px 64px repeat-y,var(--vc-sidebar-bg) !important; padding-left:12px; }
[data-chat-row]{ clip-path:var(--vc-tag); border-radius:0 !important; }
[data-chat-row][data-selected="true"]{ background:color-mix(in srgb,var(--vc-accent) 24%,var(--vc-ground)) !important; }
[data-chat-row] [data-mari-part="avatar-placeholder"],[data-chat-row] img{ border-radius:50% / 50%; }
.ov-new-pill,.mari-chrome-control--primary,.ov-btn--primary{
  clip-path:var(--vc-tag); border-radius:0 !important; padding-inline:16px !important;
  font-family:var(--vc-plate); font-weight:700; letter-spacing:.04em;
  background:var(--vc-accent) !important; color:#fff !important; border:0 !important;
}
[data-component="CenterContent"] .mari-chrome-control:not(.mari-chrome-control--primary){ background-color:var(--vc-panel) !important; }
.mari-chrome-segmented__button{ font-family:var(--vc-plate); font-weight:700; letter-spacing:.04em; border-radius:0 !important; clip-path:var(--vc-tag); }

/* ── Avatars: mourning cameos ─────────────────────────────── */
.mari-roleplay-message-row [data-mari-part="avatar"] button{
  border-radius:50% / 50% !important; height:calc(3.25rem * var(--roleplay-avatar-scale,1)) !important; width:calc(2.6rem * var(--roleplay-avatar-scale,1)) !important;
  box-shadow:0 0 0 2px var(--vc-lining),0 0 0 4px var(--vc-trim) !important; --tw-ring-color:transparent;
}
.mari-roleplay-message-row [data-mari-part="avatar"] .rpg-avatar-glow{ filter:none; box-shadow:none; background:none; }
[data-component="ConversationMessage.Content"] [data-mari-part="avatar"] button{
  border-radius:50% / 50% !important; width:2.2rem !important; height:2.6rem !important;
  box-shadow:0 0 0 2px var(--vc-lining),0 0 0 3.5px var(--vc-trim);
}
[data-component="ConversationMessage.Content"] [data-mari-part="avatar"]{ max-height:none; }

/* ── Roleplay: each message is an upright coffin with a finial ── */
.mari-rp-bubble{
  clip-path:var(--vc-coffin); border:0 !important; border-radius:0 !important;
  background:var(--vc-trim) !important; isolation:isolate; box-shadow:none !important; backdrop-filter:none !important;
}
.mari-rp-bubble::before{
  content:""; position:absolute; inset:var(--vc-bw); z-index:-1; clip-path:var(--vc-coffin-in);
  background:var(--vc-lining-layers);
}
.mari-rp-bubble--user::before{ background:var(--vc-lining-user-layers); }
.mari-rp-bubble > div{ padding:18px calc(var(--vc-foot) + 16px) 20px calc(var(--vc-foot) + 16px) !important; }
.mari-roleplay-message-body{ position:relative; }
.mari-roleplay-message-body::before{
  content:""; position:absolute; left:50%; top:-15px; width:26px; height:36px; translate:-50% 0; z-index:2; pointer-events:none;
  background:var(--vc-finial) center / contain no-repeat;
}
[data-message-role="user"] .mari-roleplay-message-body::before{ background-image:var(--vc-finial-user); left:auto; right:30px; translate:0 0; width:28px; height:28px; top:-14px; }
[data-mari-part="message"] .mari-message-name{ font-family:var(--vc-plate) !important; font-size:1.0625rem !important; font-weight:700; letter-spacing:.05em; color:var(--vc-name) !important; }
[data-mari-part="message"][data-latest] .mari-rp-bubble{ background:var(--vc-latest-trim) !important; }
[data-mari-part="message"][data-latest][data-message-role="assistant"] .mari-roleplay-message-body::before{ background-image:var(--vc-finial-latest); }
.mari-roleplay-message-row{ margin-bottom:2rem !important; }
[data-mari-part="time"]{ font-family:var(--vc-serif); font-size:.8125rem !important; }
[data-mari-part="message"] hr{ border:0; height:22px; margin:1.1em auto; background:var(--vc-scene-break) center / auto 22px no-repeat,linear-gradient(var(--vc-hair),var(--vc-hair)) center / 100% 1px no-repeat; }

/* ── Composer: a coffin laid on its side ──────────────────── */
[data-mari-part="composer"] .mari-chat-input-box{
  clip-path:var(--vc-coffin-side); border:0 !important; border-radius:0 !important; isolation:isolate;
  background:var(--vc-trim) !important; padding-left:34px !important; padding-right:20px !important; box-shadow:none !important; backdrop-filter:none !important;
}
[data-mari-part="composer"] .mari-chat-input-box::before{
  content:""; position:absolute; inset:var(--vc-bw); z-index:-1; clip-path:var(--vc-coffin-side);
  background:var(--vc-lining-layers);
}
[data-mari-part="composer"] textarea{ font-family:var(--vc-serif) !important; font-size:1.0625rem !important; color:var(--vc-ink) !important; }
[data-mari-part="composer"] textarea::placeholder{ color:var(--vc-faint) !important; font-style:italic; }

/* ── Conversation: a mourning ledger ──────────────────────── */
[data-mari-part="chat-header"] > *{ clip-path:var(--vc-tag); border-radius:0 !important; }
[data-component="ConversationMessage.Content"] .mari-message-content{ font-size:1.0625rem; }
/* the whole transcript is written inside one long coffin lid (a picture, so the scrollbar is never cut) */
[data-chat-mode="conversation"] .mari-messages-scroll{ background:var(--vc-lid) center top / calc(100% - 20px) 100% no-repeat; padding-inline:22px; }

/* ── Game: narration in a coffin ──────────────────────────── */
[data-mari-part="message"][data-game-narration]{
  position:relative;
  clip-path:var(--vc-coffin); border:0 !important; border-radius:0 !important; isolation:isolate;
  background:var(--vc-trim) !important; box-shadow:none !important; backdrop-filter:none !important;
  padding:20px 28px 16px !important;
}
[data-mari-part="message"][data-game-narration]::before{
  content:""; position:absolute; inset:var(--vc-bw); z-index:-1; clip-path:var(--vc-coffin-in); background:var(--vc-lining-layers);
}
[data-mari-part="message"][data-game-narration] .game-narration-prose{ border-color:var(--vc-hair) !important; background:transparent !important; border-radius:0 !important; font-size:1.0625rem; }
[data-mari-part="message"][data-game-narration] .game-narration-prose .text-sm{ font-size:1.0625rem; line-height:1.6; }
[data-mari-part="game-hud"]{ clip-path:var(--vc-coffin); border-radius:0 !important; background:var(--vc-panel) !important; padding-inline:14px; }

/* ── Home: a row of coffins ───────────────────────────────── */
[data-mari-part="home-widget"]{
  clip-path:var(--vc-coffin); border:0 !important; border-radius:0 !important; isolation:isolate;
  background:var(--vc-trim) !important; box-shadow:none !important; backdrop-filter:none !important;
}
[data-mari-part="home-widget"]::before{
  content:""; position:absolute; inset:var(--vc-bw); z-index:-1; clip-path:var(--vc-coffin-in);
  background:var(--vc-lining-layers);
}
[data-mari-part="home-widget"] > header,[data-mari-part="home-widget"] > div:not([data-home-professor-content]){ padding-inline:12px; }
[data-mari-part="home-widget-eyebrow"]{ font-family:var(--vc-plate) !important; letter-spacing:.14em; font-weight:700; }
[data-mari-part="home-widget-glow"]{ display:none !important; }
[data-mari-part="home-widget-title"]{ line-height:1.15 !important; margin-bottom:.35rem; letter-spacing:.01em; }
[data-home-professor-content]{ padding-left:14px; }
[data-mari-part="home-widget"]::after{
