:root[data-overhaul="mobile"][data-theme="light"] [data-component="TopBar"]{ min-height:0; padding-bottom:26px !important; }
/* Phone: a compact toast docked above the bottom bar, clear of the mode tabs */
:root[data-overhaul="mobile"] [data-sonner-toast]{ padding:8px 40px 8px 44px !important; background-size:20px 20px,auto !important; background-position:left 16px center,0 0 !important; font-size:.875rem !important; min-height:0 !important; }
:root[data-overhaul="mobile"] [data-sonner-toast] [data-close-button]{ right:16px !important; }
/* Loading and icon avatars in the chat list are cameo ovals too */
[data-chat-row] > .relative.flex-shrink-0 [class*="rounded-"]:not(.rounded-full),[data-chat-row] [data-mari-part="avatar-placeholder"]{ border-radius:50% / 50% !important; }
/* Library: the "new" card is an empty coffin with a dashed edge and a sticker */
.ov-card__art--new{ clip-path:var(--vc-coffin); --vc-head:16px; --vc-sh:16px; --vc-foot:10px; border:0 !important; border-radius:0 !important; position:relative; isolation:isolate;
  background:var(--vc-card-new) 0 0 / 100% 100% no-repeat,var(--vc-card-ph) !important; color:var(--vc-name) !important; }
:root,:root[data-theme="dark"]{ --vc-card-new:url("theme:card-new-night.svg"); }
:root[data-theme="light"]{ --vc-card-new:url("theme:card-new-day.svg"); }
.ov-card__art--new::before{ content:""; position:absolute; left:50%; top:22%; width:46px; height:46px; translate:-50% 0; z-index:-1; pointer-events:none; background:var(--vc-finial) center / contain no-repeat; }
.ov-card__art--new svg{ margin-top:48px; }

/* ══ Round 5 ══════════════════════════════════════════════ */
/* Sidebar mode tabs: a shallower tag and tighter tracking, so the count sits inside the shape */
[data-component="ChatSidebar"] .mari-chrome-segmented__button{ clip-path:polygon(6px 0,calc(100% - 6px) 0,100% 50%,calc(100% - 6px) 100%,6px 100%,0 50%); padding-inline:10px !important; letter-spacing:.01em; gap:3px; }
[data-component="ChatSidebar"] .mari-chrome-segmented__button .ov-mode-count{ margin-left:2px; }
/* Day selects: lilac lining and a plum trim, like the rest of the pastel forms */
:root[data-theme="light"] [data-component="OverhaulSettingsPage"] select{ background-color:#ecdfff !important; border-color:#8a5aa8 !important; color:var(--vc-ink) !important; }
/* Settings boxes (such as Custom sound) get room inside their edge */
[data-component="OverhaulSettingsPage"] .rounded-lg.p-2\.5{ padding:12px 14px !important; border-radius:0 !important; }

/* Night sidebars: the velvet is softened further so no streak shows behind the list */
:root,:root[data-theme="dark"]{ --vc-sidebar-bg:linear-gradient(rgba(12,6,9,.74),rgba(12,6,9,.8)),url("theme:velvet-tile.webp") 0 0 / 512px repeat,#120609; }

/* ══ Round 6: a smaller toast (its position stays the user's Notification position) ══ */
:root:not([data-overhaul="mobile"]) [data-sonner-toaster]{ --width:min(420px,calc(100vw - 48px)) !important; }
[data-sonner-toast] [data-content]{ min-width:0; flex:1 1 auto; }
[data-sonner-toast] [data-title],[data-sonner-toast] [data-description]{ white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
[data-sonner-toast] [data-description]{ font-size:.875rem !important; }
:root[data-overhaul="mobile"] [data-sonner-toast] [data-content]{ font-size:.875rem; }
/* phone: one line, the title and its Refresh button */
:root[data-overhaul="mobile"] [data-sonner-toast] [data-description]{ display:none !important; }
/* phone, toasts at the bottom: the chat keeps room so the newest reply is not under the toast */
:root[data-overhaul="mobile"]:has([data-sonner-toaster][data-y-position="bottom"] [data-sonner-toast]) .mari-messages-scroll{ padding-bottom:200px !important; scroll-padding-bottom:200px; }

/* ══ Round 7: the name-plate ornament sits dead centre ══ */
/* the plate lines its text up on the baseline, so the ornament centres itself on both axes */
[data-mari-part="header"][data-placement="outside"]::before{ align-self:center; width:28px; height:24px; background-position:center; background-size:contain; margin-block:0; }
